impl Rule for NoUnknownUnit {
    type Query = Ast<AnyCssDimension>;
    type State = CssSyntaxToken;
    type Signals = Option<Self::State>;
    type Options = ();

    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
        let node = ctx.query();

        // A percentage is always a valid dimension.
        let unit_token = match node {
            AnyCssDimension::CssPercentage(_) => return None,
            AnyCssDimension::CssRegularDimension(dimension) => dimension.unit_token().ok()?,
            AnyCssDimension::CssUnknownDimension(dimension) => dimension.unit_token().ok()?,
        };

        let unit = unit_token.text_trimmed();

        // Units are case-insensitive, so normalize before comparing.
        let normalized_unit = unit.to_ascii_lowercase();

        // The `x` unit is a resolution unit and is only valid in resolution
        // contexts, such as the `image-set()` function, the `resolution` media
        // feature, or the `image-resolution` property.
        if normalized_unit == "x" {
            if is_in_resolution_context(node.syntax()) {
                return None;
            }
            return Some(unit_token);
        }

        if is_known_unit(&normalized_unit) {
            return None;
        }

        Some(unit_token)
    }

    fn diagnostic(_: &RuleContext<Self>, unit_token: &Self::State) -> Option<RuleDiagnostic> {
        let unit = unit_token.text_trimmed();
        Some(
            RuleDiagnostic::new(
                rule_category!(),
                unit_token.text_trimmed_range(),
                markup! {
                    "Unexpected unknown unit: "<Emphasis>{unit}</Emphasis>
