/// Determines whether the given dimension node lives in a context where the `x`
/// resolution unit is valid.
fn is_in_resolution_context(node: &CssSyntaxNode) -> bool {
    for ancestor in node.ancestors() {
        match ancestor.kind() {
            CssSyntaxKind::CSS_FUNCTION => {
                if let Some(function) = CssFunction::cast_ref(&ancestor) {
                    if let Ok(name) = function.name() {
                        if let Ok(name_token) = name.value_token() {
                            let name = name_token.text_trimmed().to_ascii_lowercase();
                            if name == "image-set" || name == "-webkit-image-set" {
                                return true;
                            }
                        }
                    }
                }
            }
            CssSyntaxKind::CSS_QUERY_FEATURE_PLAIN
            | CssSyntaxKind::CSS_QUERY_FEATURE_RANGE
            | CssSyntaxKind::CSS_QUERY_FEATURE_RANGE_INTERVAL
            | CssSyntaxKind::CSS_QUERY_FEATURE_REVERSE_RANGE => {
                if let Some(name) = query_feature_name(&ancestor) {
                    if is_resolution_feature(&name) {
                        return true;
                    }
                }
            }
            CssSyntaxKind::CSS_GENERIC_PROPERTY => {
                if let Some(property) = CssGenericProperty::cast_ref(&ancestor) {
                    if let Ok(name) = property.name() {
                        if name
                            .syntax()
                            .text_trimmed()
                            .to_string()
                            .eq_ignore_ascii_case("image-resolution")
                        {
                            return true;
                        }
                    }
                }
            }
            _ => {}
        }
    }

    false
}

